internal val Dark=darkColorScheme(primary=Mint,onPrimary=Color(0xff00382d),background=Color(0xff0b121b),surface=Color(0xff111d29),surfaceVariant=Color(0xff1c2b39),onSurface=Color(0xffe9f1f8),onSurfaceVariant=Color(0xffa7bacb),secondary=Color(0xff90bfff),secondaryContainer=Color(0xff16372f),error=Color(0xffff9eab),outline=Color(0xff354959))
