fun bytes(n:Double):String{if(!n.isFinite()||n<0)return "—";val units=listOf("B","KiB","MiB","GiB","TiB");var x=n;var i=0;while(x>=1024&&i<units.lastIndex){x/=1024;i++};return (if(x>=100||i==0)"%.0f" else "%.1f").format(Locale.US,x)+" "+units[i]}
fun uptime(seconds:Double):String{val s=seconds.toLong();return when{ s>=86400->"${s/86400}d ${s%86400/3600}h";s>=3600->"${s/3600}h ${s%3600/60}m";else->"${s/60}m"}}
internal fun array(v:Any?):List<JSONObject>{val a=v as? JSONArray?:return emptyList();return (0 until a.length()).mapNotNull{a.optJSONObject(it)}}
internal fun result(s:ScreenState,host:String,action:String)=s.results["$host:$action"]
private fun number(v:JSONObject?,field:String):Double?=if(v!=null&&v.has(field)&&!v.isNull(field))v.optDouble(field).takeIf{it.isFinite()}else null
internal fun copy(text:String){Controller.app.getSystemService(ClipboardManager::class.java).setPrimaryClip(ClipData.newPlainText("Deco Control",text));Controller.toast("Copied")}
internal fun share(path:String){val f=File(path);if(!f.isFile){Controller.toast("File not found");return};val uri=FileProvider.getUriForFile(Controller.app,"${Controller.app.packageName}.files",f);val intent=Intent(Intent.ACTION_SEND).setType(if(path.endsWith(".json"))"application/json" else "application/octet-stream").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);Controller.app.startActivity(Intent.createChooser(intent,"Save a copy").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}

