@Composable internal fun IconGlyph(name:String){val c=LocalContentColor.current;Canvas(Modifier.size(23.dp)){val w=size.width;val h=size.height;val sw=2.dp.toPx();fun line(a:Float,b:Float,x:Float,y:Float)=drawLine(c,Offset(w*a,h*b),Offset(w*x,h*y),sw,StrokeCap.Round)
 when(name){"terminal"->{line(.15f,.25f,.4f,.5f);line(.4f,.5f,.15f,.75f);line(.53f,.75f,.85f,.75f)};"nodes"->{for(x in listOf(.13f,.57f))for(y in listOf(.13f,.57f))drawRoundRect(c,Offset(w*x,h*y),androidx.compose.ui.geometry.Size(w*.3f,h*.3f),androidx.compose.ui.geometry.CornerRadius(w*.05f),style=Stroke(sw))};"chart"->{line(.1f,.82f,.1f,.15f);line(.1f,.82f,.9f,.82f);line(.22f,.65f,.42f,.45f);line(.42f,.45f,.62f,.58f);line(.62f,.58f,.85f,.25f)};"files"->{val p=Path().apply{moveTo(w*.12f,h*.2f);lineTo(w*.4f,h*.2f);lineTo(w*.5f,h*.32f);lineTo(w*.9f,h*.32f);lineTo(w*.9f,h*.85f);lineTo(w*.12f,h*.85f);close()};drawPath(p,c,style=Stroke(sw))};else->{drawCircle(c,w*.24f,Offset(w*.5f,h*.5f),style=Stroke(sw));for(i in 0..7){val a=i*PI/4;line((.5+cos(a)*.33).toFloat(),(.5+sin(a)*.33).toFloat(),(.5+cos(a)*.44).toFloat(),(.5+sin(a)*.44).toFloat())}}}
}}
