   "ssh_health"->{val d=result(s,host,action) as? JSONObject;val last=d?.optJSONObject("last_connection");LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Panel{Text(when{d==null->if("$host:ssh_health" in s.loading)"Checking connection…" else "No measurement yet";d.optBoolean("tcp_ok")&&d.optBoolean("banner_ok")->"SSH is responding";d.optBoolean("tcp_ok")->"Port reachable; SSH response delayed";else->"TCP connection failed"},style=MaterialTheme.typography.titleMedium);KeyValue("TCP connection",number(d,"tcp_ms")?.let{"%.0f ms".format(it)}?:"No response");KeyValue("SSH banner",number(d,"banner_ms")?.let{"%.0f ms".format(it)}?:"No response");KeyValue("Key exchange and sign-in",number(last,"key_exchange_and_auth_ms")?.let{"%.0f ms".format(it)}?:"Not measured yet");KeyValue("SSH server",d?.optString("banner").orEmpty());d?.optString("error")?.takeIf{it.isNotBlank()}?.let{Text(it,color=MaterialTheme.colorScheme.error)};Text("Existing sessions are reused. This check does not restart Dropbear.",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}};d?.optJSONObject("server")?.let{server->item{Panel{KeyValue("System load",server.optString("load"));KeyValue("Entropy",server.optString("entropy"));Text("SSH events",fontWeight=FontWeight.SemiBold);SelectionContainer{Text(server.optString("logs").ifBlank{"No events"},fontFamily=FontFamily.Monospace,fontSize=11.sp)}}}}}}
   "operation"->OperationPage(s,{onDialog("continue_root")},{onDialog("retry_root")})
   "history"->LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){val events=s.events.filter{it.host==host};if(events.isEmpty())item{Empty("No events yet","Operation results for this Deco appear here")};items(events.reversed()){e->Panel{Text(SimpleDateFormat("HH:mm:ss",Locale.US).format(Date(e.time)),style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.onSurfaceVariant);Text(e.text)}};item{OutlinedButton(onClick={Controller.read("export_report",host=host)}){Text("Prepare report")};val report=result(s,host,"export_report") as? JSONObject;report?.optString("path")?.takeIf{it.isNotBlank()}?.let{path->TextButton(onClick={share(path)}){Text("Save report without passwords")}}}}
   "backups"->BackupsPage(s,host)
   "interfaces"->LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){items(array(node?.metrics?.opt("interfaces"))){n->Panel{Row{Text(n.optString("name"),fontWeight=FontWeight.Bold,modifier=Modifier.weight(1f));Text(n.optString("state"),color=MaterialTheme.colorScheme.primary)};Text(n.optString("mac"),fontFamily=FontFamily.Monospace,fontSize=12.sp);KeyValue("Received",bytes(n.optDouble("rx")));KeyValue("Sent",bytes(n.optDouble("tx")));KeyValue("Receive rate",number(n,"rx_per_second")?.let{bytes(it)+"/s"}?:"Reading data");KeyValue("Send rate",number(n,"tx_per_second")?.let{bytes(it)+"/s"}?:"Reading data");KeyValue("RX / TX errors","${n.optLong("rx_errors")} / ${n.optLong("tx_errors")}")}}}
   "logs"->{var query by remember(host){mutableStateOf("")};OutlinedTextField(query,{query=it},Modifier.fillMaxWidth().padding(horizontal=20.dp),label={Text("Search log")},singleLine=true);val raw=(result(s,host,"logs") as? JSONObject)?.optString("text").orEmpty();val filtered=raw.lines().filter{query.isBlank()||it.contains(query,true)}.joinToString("\n");Row(Modifier.padding(horizontal=16.dp)){TextButton(onClick={copy(filtered)}){Text("Copy")};Text("${filtered.lines().count{it.isNotBlank()}} lines",modifier=Modifier.padding(12.dp),style=MaterialTheme.typography.labelSmall)};RawText(filtered.ifBlank{if(raw.isBlank())"The log is empty" else "No matches"})}
   "diagnostics"->{val d=result(s,host,action) as? JSONObject;LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Panel{KeyValue("Device",d?.optString("model").orEmpty());KeyValue("Kernel",d?.optString("kernel").orEmpty());KeyValue("Architecture",d?.optString("architecture").orEmpty());KeyValue("Image in RAM",when(d?.optString("kernel_image_loaded")){"1"->"Prepared";"0"->"Not loaded";else->"Unavailable"});KeyValue("Kernel switch",if(d?.optString("restart_armed")=="N")"Disabled" else d?.optString("restart_armed")?.ifBlank{"Not armed"}?:"Unavailable")}};listOf("mtd" to "NAND map","version" to "Firmware","routes" to "Routes","tcp" to "TCP IPv4","tcp6" to "TCP IPv6","dmesg" to "Kernel messages").forEach{(key,label)->item{Panel{Text(label,fontWeight=FontWeight.SemiBold);SelectionContainer{Text(d?.optString(key).orEmpty().ifBlank{"Data unavailable"},fontFamily=FontFamily.Monospace,fontSize=11.sp)}}}}}}
   "processes"->{val list=array(result(s,host,action));LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text("${list.size} processes · sorted by memory",color=MaterialTheme.colorScheme.onSurfaceVariant)};items(list){p->Panel{Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(p.optString("name"),fontWeight=FontWeight.SemiBold);Text("PID ${p.optInt("pid")} · ${p.optInt("threads")} threads",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};Text(bytes(p.optLong("rss_kib")*1024.0),fontFamily=FontFamily.Monospace)};Text(p.optString("state"),style=MaterialTheme.typography.labelSmall)}};item{Button(onClick={Controller.tab(3)}){Text("Open terminal")}}}}
