  }
  s.errors["$host:$action"]?.let{Text(it,color=MaterialTheme.colorScheme.error,modifier=Modifier.padding(20.dp))};if("$host:$action" in s.loading)LinearProgressIndicator(Modifier.fillMaxWidth())
 }
