fun parseClients(v:JSONObject):List<Pair<String,String>>{val raw=v.optString("raw");val mac=Regex("(?i)([0-9a-f]{2}:){5}[0-9a-f]{2}");return if(v.optString("source")=="iw")raw.split(Regex("(?m)^Station ")).drop(1).mapNotNull{block->val id=mac.find(block)?.value?:return@mapNotNull null;val signal=Regex("(?m)^\\s*signal:\\s*([^\\n]+)").find(block)?.groupValues?.get(1).orEmpty();val rate=Regex("(?m)^\\s*tx bitrate:\\s*([^\\n]+)").find(block)?.groupValues?.get(1).orEmpty();id to listOf(signal,rate).filter{it.isNotBlank()}.joinToString(" · ")}
 else{val lines=raw.lines();val header=lines.firstOrNull{it.contains("ADDR")&&it.contains("RSSI")};val index=header?.trim()?.split(Regex("\\s+"))?.indexOf("RSSI")?:-1;lines.mapNotNull{line->val id=mac.find(line)?.value?:return@mapNotNull null;val fields=line.trim().split(Regex("\\s+"));id to if(index>=0&&index<fields.size)"RSSI ${fields[index]}" else ""}}}
