@Composable private fun RawText(text:String){SelectionContainer(Modifier.fillMaxSize().padding(16.dp).verticalScroll(rememberScrollState()).horizontalScroll(rememberScrollState())){Text(text,fontFamily=FontFamily.Monospace,fontSize=12.sp)}}
@Composable private fun OperationPage(s:ScreenState,onContinue:()->Unit,onRetry:()->Unit){val op=s.operation;if(op==null){Empty("No operations","Choose an action from Tools");return};LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Panel{Text(op.host,fontFamily=FontFamily.Monospace,color=MaterialTheme.colorScheme.primary);Text(op.stage,style=MaterialTheme.typography.titleMedium);if(op.running)LinearProgressIndicator(Modifier.fillMaxWidth());op.error?.let{message->SelectionContainer{Text(message,color=MaterialTheme.colorScheme.error)};TextButton(onClick={copy(message)}){Text("Copy error")}};if(!op.running&&op.error!=null&&op.action in listOf("install","continue_install","password","result","bootstrap"))Button(onClick={Controller.mutate("result",host=op.host)}){Text("Check result")};if(op.action.startsWith("ram_"))Button(onClick={Controller.select(op.host);Controller.page("openwrt")}){Text("Open RAM boot details")};op.result?.let{r->if(r.optBoolean("include_ready"))Button(onClick=onContinue){Text("Continue SSH installation")};if(r.optBoolean("prewrite_stopped"))OutlinedButton(onClick=onRetry){Text("Retry preflight")};Text(when{op.action.startsWith("ram_")->ramOperationTitle(op.action,r);r.optBoolean("include_ready")->"Startup configuration is saved and verified. Continue to install personal SSH access.";r.optBoolean("prewrite_stopped")->"The check stopped before saving configuration.";r.optBoolean("not_applied")->"The password change was not applied. Check the current SSH access.";r.optBoolean("installed")->"Permanent SSH is ready. The Deco has not been rebooted.";r.optBoolean("changed")->"SSH password changed.";r.optBoolean("verified")->"Backup verified.";r.has("verified_partitions")->"Verified ${r.optInt("verified_partitions")} NAND partitions.";r.optBoolean("scheduled")->"Reboot scheduled.";r.has("distinct_post_install_boots")->"Verified boots: ${r.optInt("distinct_post_install_boots")} of 2.";r.has("seconds")->"Indicator blink duration: ${r.optInt("seconds")} seconds.";else->"Operation complete."})};if(!op.running)TextButton(onClick={Controller.clearOperation();Controller.page("")}){Text("Done")}}};items(s.events.filter{it.host==op.host}.reversed().take(60)){e->Text(e.text,color=MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.bodySmall)}}}
@Composable private fun BackupsPage(s:ScreenState,host:String){var tick by remember{mutableIntStateOf(0)};val folders=remember(host,s.operation,tick){File(Controller.app.filesDir,"backups/$host").listFiles()?.filter{it.isDirectory}?.sortedByDescending{it.lastModified()}?:emptyList()};var exportFile by remember{mutableStateOf<File?>(null)};val save=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/zip")){uri->if(uri!=null&&exportFile!=null)Controller.saveExport(exportFile!!,uri)}
 LazyColumn(contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{ActionRow("Back up configuration","Save a verified configuration copy to your phone","files"){Controller.mutate("backup",host=host);Controller.page("operation")}};item{ActionRow("Full NAND data backup","Visible NAND data · copies stay on your phone","files"){Controller.mutate("nand_backup",host=host);Controller.page("operation")}};item{Row{Text("Saved backups",style=MaterialTheme.typography.titleMedium,modifier=Modifier.weight(1f));TextButton(onClick={tick++}){Text("Refresh")}}};if(folders.isEmpty())item{Empty("No backups yet","Create your first configuration backup")};items(folders,key={it.path}){folder->val report=remember(folder.lastModified()){listOf("verified.json","report.json").map{File(folder,it)}.firstOrNull{it.isFile}?.let{runCatching{JSONObject(it.readText())}.getOrNull()}};Panel{Text(if(folder.name.startsWith("nand"))"NAND" else if(folder.name.startsWith("ram-"))"RAM boot environment" else "Configuration",fontWeight=FontWeight.Bold);Text(SimpleDateFormat("dd MMM yyyy, HH:mm",Locale.US).format(Date(folder.lastModified())),color=MaterialTheme.colorScheme.onSurfaceVariant);Text(if(report?.optBoolean("verified")==true||report?.optString("status")=="verified")"Backup verified" else "Partial backup · retained for inspection",color=if(report?.optBoolean("verified")==true||report?.optString("status")=="verified")MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error);TextButton(onClick={Controller.zipBackup(folder){file->exportFile=file;save.launch("Deco-$host-${folder.name}.zip")}}){Text("Save ZIP to phone")}}}}
