@Composable private fun LiveChart(points:List<Float>,maximum:Float,color:Color){val grid=MaterialTheme.colorScheme.outline.copy(alpha=.18f);Canvas(Modifier.fillMaxWidth().height(110.dp)){for(i in 0..4){val y=size.height*i/4;drawLine(grid,Offset(0f,y),Offset(size.width,y),1.dp.toPx())};val maxValue=maximum.coerceAtLeast(.01f);val path=Path();points.forEachIndexed{i,v->val x=size.width*i/(points.size-1).coerceAtLeast(1);val y=size.height*(1-v.coerceIn(0f,maxValue)/maxValue);if(i==0)path.moveTo(x,y)else path.lineTo(x,y)};drawPath(path,color,style=Stroke(2.5.dp.toPx(),cap=StrokeCap.Round))}}

fun strongPassword(value:String)=value.codePointCount(0,value.length)>=12&&value.toByteArray().size<=256&&!value.contains('\u0000')
